{"command": "cat > /workspace/create_patterns.py << 'EOF'
import json

# Note values in FT2: C-4 = 48, C#4 = 49, etc.
# We'll use note numbers directly
def note(name):
    """Convert note name to FT2 note number"""
    notes = {
        'C-3': 36, 'C#3': 37, 'D-3': 38, 'D#3': 39, 'E-3': 40, 'F-3': 41, 'F#3': 42, 'G-3': 43, 'G#3': 44, 'A-3': 45, 'A#3': 46, 'B-3': 47,
        'C-4': 48, 'C#4': 49, 'D-4': 50, 'D#4': 51, 'E-4': 52, 'F-4': 53, 'F#4': 54, 'G-4': 55, 'G#4': 56, 'A-4': 57, 'A#4': 58, 'B-4': 59,
        'C-5': 60, 'C#5': 61, 'D-5': 62, 'D#5': 63, 'E-5': 64, 'F-5': 65, 'F#5': 66, 'G-5': 67, 'G#5': 68, 'A-5': 69, 'A#5': 70, 'B-5': 71,
        'C-6': 72, 'C#6': 73, 'D-6': 74, 'D#6': 75, 'E-6': 76, 'F-6': 77, 'F#6': 78, 'G-6': 79, 'G#6': 80, 'A-6': 81, 'A#6': 82, 'B-6': 83
    }
    return notes.get(name, 0)

# Channel assignments:
# 0: Lead
# 1: Arp
# 2: Bass
# 3: Pad
# 4: Kick
# 5: Snare
# 6: HiHat
# 7: Crash

ops = []

# Set pattern lengths
for p in range(4):
    ops.append({"name": "pattern_set_length", "arguments": {"pattern": p, "rows": 64}})

# Musical key: C minor (C, Eb, F, G, Bb)
# Notes available: C-4, Eb-4, F-4, G-4, Bb-4 and octaves above/below

# Pattern 0 - Main groove
# Bassline: C-3, G-3, Bb-3, F-3 pattern
bass_pattern = [note('C-3'), note('G-3'), note('Bb-3'), note('F-3')]
# Lead melody
lead_melody = [
    note('Eb-5'), note('G-5'), note('C-6'), 0,
    note('Bb-5'), note('G-5'), note('F-5'), 0,
    note('Eb-5'), note('D-5'), note('Eb-5'), note('F-5'),
    note('G-5'), 0, note('F-5'), note('Eb-5')
]
# Arpeggio pattern
arp_pattern = [
    note('C-5'), note('Eb-5'), note('G-5'), note('Bb-5'),
    note('C-5'), note('Eb-5'), note('G-5'), note('Bb-5'),
    note('G-4'), note('Bb-4'), note('C-5'), note('Eb-5'),
    note('G-4'), note('Bb-4'), note('C-5'), note('Eb-5')
]
# Pad chord (root position)
pad_chord = note('C-4')

# Drums - standard 4/4 pattern
# Kick on 0, 8, 16, 24, 32, 40, 48, 56 (every 8 rows in 64-row pattern at speed 6)
kick_rows = [0, 8, 16, 24, 32, 40, 48, 56]
# Snare on 16, 48
snare_rows = [16, 48]
# HiHat on 4, 12, 20, 28, 36, 44, 52, 60
hh_rows = [4, 12, 20, 28, 36, 44, 52, 60]

# Build Pattern 0
for row in range(64):
    # Bass (channel 2) - every 4 rows
    if row % 4 == 0:
        bass_note = bass_pattern[(row // 4) % 4]
        if bass_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 0, "row": row, "channel": 2,
                "note": bass_note, "instrument": 2, "volume": 55
            }})

    # Lead (channel 0) - melody
    if row % 4 == 0:
        lead_idx = (row // 4) % 16
        lead_note = lead_melody[lead_idx]
        if lead_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 0, "row": row, "channel": 0,
                "note": lead_note, "instrument": 1, "volume": 60
            }})

    # Arp (channel 1) - every 2 rows, faster
    if row % 2 == 0:
        arp_idx = (row // 2) % 16
        arp_note = arp_pattern[arp_idx]
        if arp_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 0, "row": row, "channel": 1,
                "note": arp_note, "instrument": 4, "volume": 45
            }})

    # Pad (channel 3) - every 8 rows, long chords
    if row % 8 == 0:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 0, "row": row, "channel": 3,
            "note": pad_chord, "instrument": 3, "volume": 40
        }})

    # Drums
    if row in kick_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 0, "row": row, "channel": 4,
            "note": note('C-5'), "instrument": 5, "volume": 64
        }})
    if row in snare_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 0, "row": row, "channel": 5,
            "note": note('C-5'), "instrument": 6, "volume": 55
        }})
    if row in hh_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 0, "row": row, "channel": 6,
            "note": note('C-5'), "instrument": 7, "volume": 35
        }})

# Pattern 1 - Variation with different lead melody
lead_melody_2 = [
    note('G-5'), note('Bb-5'), note('C-6'), 0,
    note('Eb-6'), note('D-6'), note('C-6'), note('Bb-5'),
    note('G-5'), note('F-5'), note('G-5'), note('A-5'),
    note('Bb-5'), 0, note('A-5'), note('G-5')
]
arp_pattern_2 = [
    note('G-4'), note('Bb-4'), note('D-5'), note('F-5'),
    note('G-4'), note('Bb-4'), note('D-5'), note('F-5'),
    note('C-4'), note('Eb-4'), note('G-4'), note('Bb-4'),
    note('C-4'), note('Eb-4'), note('G-4'), note('Bb-4')
]
pad_chord_2 = note('G-3')

for row in range(64):
    # Bass
    if row % 4 == 0:
        bass_note = bass_pattern[(row // 4) % 4]
        if bass_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 1, "row": row, "channel": 2,
                "note": bass_note, "instrument": 2, "volume": 55
            }})

    # Lead
    if row % 4 == 0:
        lead_idx = (row // 4) % 16
        lead_note = lead_melody_2[lead_idx]
        if lead_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 1, "row": row, "channel": 0,
                "note": lead_note, "instrument": 1, "volume": 60
            }})

    # Arp
    if row % 2 == 0:
        arp_idx = (row // 2) % 16
        arp_note = arp_pattern_2[arp_idx]
        if arp_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 1, "row": row, "channel": 1,
                "note": arp_note, "instrument": 4, "volume": 45
            }})

    # Pad
    if row % 8 == 0:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 1, "row": row, "channel": 3,
            "note": pad_chord_2, "instrument": 3, "volume": 40
        }})

    # Drums - same
    if row in kick_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 1, "row": row, "channel": 4,
            "note": note('C-5'), "instrument": 5, "volume": 64
        }})
    if row in snare_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 1, "row": row, "channel": 5,
            "note": note('C-5'), "instrument": 6, "volume": 55
        }})
    if row in hh_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 1, "row": row, "channel": 6,
            "note": note('C-5'), "instrument": 7, "volume": 35
        }})

# Pattern 2 - Breakdown section - simpler, more space
# Slower drums, sparse melody
kick_rows_break = [0, 16, 32, 48]
snare_rows_break = [8, 24, 40, 56]
hh_rows_break = [4, 12, 20, 28, 36, 44, 52, 60]

lead_melody_break = [
    note('Eb-5'), 0, note('G-5'), 0,
    0, note('Bb-5'), 0, 0,
    note('C-6'), 0, note('Bb-5'), 0,
    note('G-5'), 0, note('F-5'), 0
]

for row in range(64):
    # Bass - simpler pattern
    if row % 8 == 0:
        bass_note = bass_pattern[(row // 8) % 4]
        if bass_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 2, "row": row, "channel": 2,
                "note": bass_note, "instrument": 2, "volume": 50
            }})

    # Lead - sparse
    if row % 4 == 0:
        lead_idx = (row // 4) % 16
        lead_note = lead_melody_break[lead_idx]
        if lead_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 2, "row": row, "channel": 0,
                "note": lead_note, "instrument": 1, "volume": 55
            }})

    # No arp in breakdown

    # Pad - longer, softer
    if row == 0:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 2, "row": row, "channel": 3,
            "note": note('C-4'), "instrument": 3, "volume": 35
        }})

    # Drums - sparse
    if row in kick_rows_break:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 2, "row": row, "channel": 4,
            "note": note('C-5'), "instrument": 5, "volume": 60
        }})
    if row in snare_rows_break:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 2, "row": row, "channel": 5,
            "note": note('C-5'), "instrument": 6, "volume": 50
        }})
    if row in hh_rows_break:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 2, "row": row, "channel": 6,
            "note": note('C-5'), "instrument": 7, "volume": 30
        }})

# Pattern 3 - Build up back to full - add crash at start
# Add crash on row 0
ops.append({"name": "pattern_set_cell", "arguments": {
    "pattern": 3, "row": 0, "channel": 7,
    "note": note('C-5'), "instrument": 8, "volume": 50
}})

lead_melody_3 = [
    note('C-5'), note('Eb-5'), note('G-5'), note('Bb-5'),
    note('C-6'), note('Bb-5'), note('G-5'), note('Eb-5'),
    note('D-5'), note('F-5'), note('A-5'), note('C-6'),
    note('Bb-5'), note('G-5'), note('F-5'), note('Eb-5')
]

for row in range(64):
    # Bass - back to full pattern
    if row % 4 == 0:
        bass_note = bass_pattern[(row // 4) % 4]
        if bass_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 3, "row": row, "channel": 2,
                "note": bass_note, "instrument": 2, "volume": 55
            }})

    # Lead - ascending line
    if row % 4 == 0:
        lead_idx = (row // 4) % 16
        lead_note = lead_melody_3[lead_idx]
        if lead_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 3, "row": row, "channel": 0,
                "note": lead_note, "instrument": 1, "volume": 62
