    "note": note('C-5'), "instrument": 8, "volume": 50
}})

lead_melody_3 = [
    note('C-5'), note('Eb-5'), note('G-5'), note('Bb-5'),
    note('C-6'), note('Bb-5'), note('G-5'), note('Eb-5'),
    note('D-5'), note('F-5'), note('A-5'), note('C-6'),
    note('Bb-5'), note('G-5'), note('F-5'), note('Eb-5')
]

for row in range(64):
    # Bass - back to full pattern
    if row % 4 == 0:
        bass_note = bass_pattern[(row // 4) % 4]
        if bass_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 3, "row": row, "channel": 2,
                "note": bass_note, "instrument": 2, "volume": 55
            }})

    # Lead - ascending line
    if row % 4 == 0:
        lead_idx = (row // 4) % 16
        lead_note = lead_melody_3[lead_idx]
        if lead_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 3, "row": row, "channel": 0,
                "note": lead_note, "instrument": 1, "volume": 62
            }})

    # Arp - back
    if row % 2 == 0:
        arp_idx = (row // 2) % 16
        arp_note = arp_pattern[arp_idx]
        if arp_note:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 3, "row": row, "channel": 1,
                "note": arp_note, "instrument": 4, "volume": 48
            }})

    # Pad
    if row % 8 == 0:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 3, "row": row, "channel": 3,
            "note": pad_chord, "instrument": 3, "volume": 42
        }})

    # Drums - full pattern
    if row in kick_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 3, "row": row, "channel": 4,
            "note": note('C-5'), "instrument": 5, "volume": 64
        }})
    if row in snare_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 3, "row": row, "channel": 5,
            "note": note('C-5'), "instrument": 6, "volume": 55
        }})
    if row in hh_rows:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 3, "row": row, "channel": 6,
            "note": note('C-5'), "instrument": 7, "volume": 35
        }})

print(f"Total pattern operations: {len(ops)}")

with open('/workspace/patterns_batch.json', 'w') as f:
    json.dump(ops, f)

print("Pattern batch file written")
