import json

# Note values: C-4 = 48
def note(name):
    notes = {
        'C-3': 36, 'D-3': 38, 'E-3': 40, 'F-3': 41, 'G-3': 43, 'A-3': 45, 'B-3': 47,
        'C-4': 48, 'D-4': 50, 'E-4': 52, 'F-4': 53, 'G-4': 55, 'A-4': 57, 'B-4': 59,
        'C-5': 60, 'D-5': 62, 'E-5': 64, 'F-5': 65, 'G-5': 67, 'A-5': 69, 'B-5': 71,
        'C-6': 72, 'D-6': 74, 'E-6': 76, 'F-6': 77, 'G-6': 79, 'A-6': 81, 'B-6': 83
    }
    return notes.get(name, 0)

ops = []

# Set pattern length
ops.append({"name": "pattern_set_length", "arguments": {"pattern": 0, "rows": 64}})

# Simple C minor bassline: C-3, G-3, Bb-3, F-3
bass_notes = [note('C-3'), note('G-3'), note('A-3'), note('F-3')]  # A-3 instead of Bb-3 for simplicity

# Simple lead melody in C minor pentatonic
lead_notes = [
    note('C-5'), note('Eb-5'), note('F-5'), note('G-5'),
    note('C-6'), note('G-5'), note('F-5'), note('Eb-5'),
    note('D-5'), note('C-5'), note('D-5'), note('F-5'),
    note('G-5'), 0, note('F-5'), note('Eb-5')
]

# Arpeggio
arp_notes = [
    note('C-5'), note('Eb-5'), note('G-5'), note('C-6'),
    note('G-5'), note('Eb-5'), note('C-5'), note('G-4'),
    note('C-5'), note('Eb-5'), note('G-5'), note('C-6'),
    note('G-5'), note('Eb-5'), note('C-5'), note('G-4')
]

# Build pattern
for row in range(64):
    # Bass every 4 rows
    if row % 4 == 0:
        bnote = bass_notes[(row // 4) % 4]
        if bnote:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 0, "row": row, "channel": 2,
                "note": bnote, "instrument": 2, "volume": 55
            }})

    # Lead every 4 rows
    if row % 4 == 0:
        lnote = lead_notes[(row // 4) % 16]
        if lnote:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 0, "row": row, "channel": 0,
                "note": lnote, "instrument": 1, "volume": 60
            }})

    # Arp every 2 rows
    if row % 2 == 0:
        anote = arp_notes[(row // 2) % 16]
        if anote:
            ops.append({"name": "pattern_set_cell", "arguments": {
                "pattern": 0, "row": row, "channel": 1,
                "note": anote, "instrument": 4, "volume": 45
            }})

    # Pad every 8 rows
    if row % 8 == 0:
        ops.append({"name": "pattern_set_cell", "arguments": {
            "pattern": 0, "row": row, "channel": 3,
            "note": note('C-4'), "instrument": 3, "volume": 40
        }})

    # Drums
    if row % 8 == 0:  # Kick
